import { Component, EventEmitter, Input, Output } from '@angular/core';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';

/**
* @deprecated replaced by espd-badge
*/
@Component({
	selector: 'espd-pill',
	templateUrl: './pill.component.html',
	imports: [
		MessageModule,
		IconDirective
	],
	styleUrls: ['./pill.component.scss']
})
export class PillComponent {

	@Input()
	public label?: MessageConfig | string;

	@Input()
	public removable = false;

	@Output()
	readonly remove: EventEmitter<void> = new EventEmitter<void>();

	onRemove(): void {
		this.remove.emit();
	}
}